SELECT 'dong_cua_ca' AS k, COUNT(*) AS v FROM kho_ca_them WHERE ma_ca = '269409'
UNION ALL SELECT 'dong_co_dap_an', COUNT(*) FROM kho_ca_them WHERE ma_ca = '269409' AND TRIM(COALESCE(dap_an, '')) <> ''
UNION ALL SELECT 'trong_217_thieu', COUNT(*) FROM kho_ca_them WHERE ma_ca = '269409' AND qid IN (SELECT qid FROM t)
UNION ALL SELECT 'trong_217_thieu_co_dap_an', COUNT(*) FROM kho_ca_them WHERE ma_ca = '269409' AND TRIM(COALESCE(dap_an, '')) <> '' AND qid IN (SELECT qid FROM t)
UNION ALL SELECT 'do_dai_dap_an_' || LENGTH(COALESCE(dap_an, '')), COUNT(*) FROM kho_ca_them WHERE ma_ca = '269409' AND qid IN (SELECT qid FROM t) GROUP BY LENGTH(COALESCE(dap_an, ''))
UNION ALL SELECT 'dong_cua_ca_khac', COUNT(*) FROM kho_ca_them WHERE ma_ca <> '269409'
